WITH daily_sales AS (SELECT cs.cs_sold_date_sk AS date_sk, sm.sm_type AS ship_mode_type, p.p_promo_id AS promo_id, SUM(cs.cs_net_paid) AS catalog_net_paid, 0 AS web_net_paid FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk AND cs.cs_sold_date_sk BETWEEN p.p_start_date_sk AND p.p_end_date_sk GROUP BY cs.cs_sold_date_sk, sm.sm_type, p.p_promo_id UNION ALL SELECT ws.ws_sold_date_sk AS date_sk, sm.sm_type AS ship_mode_type, p.p_promo_id AS promo_id, 0 AS catalog_net_paid, SUM(ws.ws_net_paid) AS web_net_paid FROM web_sales ws JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk AND ws.ws_sold_date_sk BETWEEN p.p_start_date_sk AND p.p_end_date_sk GROUP BY ws.ws_sold_date_sk, sm.sm_type, p.p_promo_id), aggregated AS (SELECT date_sk, ship_mode_type, promo_id, SUM(catalog_net_paid) AS catalog_net_paid, SUM(web_net_paid) AS web_net_paid, SUM(catalog_net_paid + web_net_paid) AS total_net_paid FROM daily_sales GROUP BY date_sk, ship_mode_type, promo_id) SELECT date_sk, ship_mode_type, promo_id, catalog_net_paid, web_net_paid, total_net_paid, SUM(total_net_paid) OVER (PARTITION BY ship_mode_type ORDER BY date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_total_by_ship_mode, LAG(total_net_paid) OVER (PARTITION BY ship_mode_type ORDER BY date_sk) AS previous_day_total, CASE WHEN LAG(total_net_paid) OVER (PARTITION BY ship_mode_type ORDER BY date_sk) IS NULL THEN 'N/A' WHEN total_net_paid > LAG(total_net_paid) OVER (PARTITION BY ship_mode_type ORDER BY date_sk) THEN 'Increase' WHEN total_net_paid < LAG(total_net_paid) OVER (PARTITION BY ship_mode_type ORDER BY date_sk) THEN 'Decrease' ELSE 'No Change' END AS day_trend FROM aggregated WHERE date_sk IS NOT NULL ORDER BY ship_mode_type, date_sk LIMIT 100
